using System;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Drawing;
using System.Windows.Forms;
using System.Diagnostics;
using System.Security.Cryptography;
using System.Text;
class InstallEngine {
 public static string DefaultPath {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GameDesignerWorkerSpace");}}
 static string Key(string root){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(root.TrimEnd(Path.DirectorySeparatorChar).ToLowerInvariant()))).Replace("-","").Substring(0,24);}
 public static void Install(string target,bool shortcut,Action<int,string> progress){target=Path.GetFullPath(target).TrimEnd(Path.DirectorySeparatorChar);Mutex running;try{running=Mutex.OpenExisting("Local\\GDWS-"+Key(target));running.Dispose();throw new Exception("工作台正在运行，请先从系统托盘退出工作台服务后安装 / 升级。");}catch(WaitHandleCannotBeOpenedException){}
  Directory.CreateDirectory(target);int total=0,count=0;using(var resource=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var archive=new ZipArchive(resource,ZipArchiveMode.Read)){foreach(var entry in archive.Entries)if(entry.Name.Length>0){total++;if(!PayloadPolicy.Allowed(entry.FullName))throw new Exception("安装包包含项目或不允许更新的路径，未执行更新。");}foreach(var entry in archive.Entries){if(entry.Name.Length==0)continue;string name=entry.FullName.Replace('\\','/');if(name!="GameDesignerWorkerSpace.exe"&&!name.StartsWith("App/")&&!name.StartsWith("Runtime/")&&!name.StartsWith("Documents/"))throw new Exception("安装内容含有不允许的路径。");string destination=Path.GetFullPath(Path.Combine(target,name.Replace('/',Path.DirectorySeparatorChar)));if(!destination.StartsWith(target+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("安装路径无效。");string directory=Path.GetDirectoryName(destination);for(string check=directory;check!=null&&check.StartsWith(target+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);check=Path.GetDirectoryName(check))if(Directory.Exists(check)&&(File.GetAttributes(check)&FileAttributes.ReparsePoint)!=0)throw new Exception("安装目标目录包含链接，请选择普通文件夹。");Directory.CreateDirectory(directory);string temp=destination+".install-tmp";using(var input=entry.Open())using(var output=File.Create(temp))input.CopyTo(output);if(File.Exists(destination))File.Delete(destination);File.Move(temp,destination);count++;progress(count*100/Math.Max(1,total),name);}}
  Directory.CreateDirectory(Path.Combine(target,"Data"));Directory.CreateDirectory(Path.Combine(target,"Logs"));if(shortcut){Type shellType=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(shellType);string desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);dynamic link=shell.CreateShortcut(Path.Combine(desktop,"GameDesignerWorkerSpace.lnk"));link.TargetPath=Path.Combine(target,"GameDesignerWorkerSpace.exe");link.WorkingDirectory=target;link.IconLocation=Path.Combine(target,"GameDesignerWorkerSpace.exe")+",0";link.Description="游戏设计与开发项目工作台";link.Save();string menu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"GameDesignerWorkerSpace");Directory.CreateDirectory(menu);dynamic start=shell.CreateShortcut(Path.Combine(menu,"GameDesignerWorkerSpace.lnk"));start.TargetPath=Path.Combine(target,"GameDesignerWorkerSpace.exe");start.WorkingDirectory=target;start.IconLocation=Path.Combine(target,"GameDesignerWorkerSpace.exe")+",0";start.Save();}
  File.WriteAllText(Path.Combine(target,"Logs","installation.log"),"Installed 1.7.1 at "+DateTime.Now.ToString("O")+Environment.NewLine+"Project and Data files were preserved.",Encoding.UTF8);
 }
}
class InstallerForm:Form {
 TextBox folder;Button install,browse;CheckBox shortcut;ProgressBar progress;Label state;bool done=false;
 public InstallerForm(string initialPath){Text="安装 GameDesignerWorkerSpace";ClientSize=new Size(620,355);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Microsoft YaHei UI",9F);BackColor=Color.FromArgb(246,249,242);Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);
  var picture=new PictureBox(){Left=27,Top=24,Width=58,Height=58,Image=Icon.ToBitmap(),SizeMode=PictureBoxSizeMode.Zoom};Controls.Add(picture);Controls.Add(new Label(){Text="GameDesignerWorkerSpace",Left=102,Top=25,Width=480,Height=35,Font=new Font("Segoe UI",17F,FontStyle.Bold),ForeColor=Color.FromArgb(42,91,65)});Controls.Add(new Label(){Text="简易安装 · 自带 Node / Git / SVN · 双击 EXE 打开网页",Left=104,Top=65,Width=470,Height=25,ForeColor=Color.FromArgb(115,139,98)});
  Controls.Add(new Label(){Text="安装位置",Left=30,Top=116,Width=540,Height=24});folder=new TextBox(){Text=initialPath,Left=30,Top=146,Width=467,Height=29};Controls.Add(folder);browse=new Button(){Text="浏览…",Left=507,Top=144,Width=82,Height=30};browse.Click+=(s,e)=>{using(var dialog=new FolderBrowserDialog()){dialog.SelectedPath=folder.Text;if(dialog.ShowDialog()==DialogResult.OK)folder.Text=dialog.SelectedPath;}};Controls.Add(browse);
  shortcut=new CheckBox(){Text="创建桌面和开始菜单快捷方式",Left=30,Top=192,Width=540,Height=25,Checked=true};Controls.Add(shortcut);Controls.Add(new Label(){Text="项目保存在独立目录。升级只更新应用和运行依赖，保留 Data 与项目内容。",Left=30,Top=224,Width=560,Height=30,ForeColor=Color.FromArgb(119,140,102)});
  progress=new ProgressBar(){Left=30,Top=267,Width=559,Height=10};Controls.Add(progress);state=new Label(){Left=30,Top=286,Width=430,Height=42,ForeColor=Color.FromArgb(119,140,102)};Controls.Add(state);install=new Button(){Text="安装",Left=490,Top=295,Width=99,Height=34,BackColor=Color.FromArgb(54,114,81),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};install.Click+=Install;Controls.Add(install);FormClosing+=(s,e)=>{if(!install.Enabled&&!done){e.Cancel=true;MessageBox.Show("安装正在进行，请稍候。","GameDesignerWorkerSpace");}};
 }
 async void Install(object sender,EventArgs e){if(done){Process.Start(new ProcessStartInfo(Path.Combine(folder.Text,"GameDesignerWorkerSpace.exe")){UseShellExecute=true});Close();return;}folder.Enabled=browse.Enabled=shortcut.Enabled=install.Enabled=false;string target=folder.Text;bool makeShortcut=shortcut.Checked;try{await Task.Run(()=>InstallEngine.Install(target,makeShortcut,(value,file)=>BeginInvoke(new Action(()=>{progress.Value=value;state.Text="正在安装内置组件… "+value+"%";}))));done=true;state.Text="安装完成。点击右侧按钮打开项目库。";install.Text="打开工作台";install.Enabled=true;}catch(Exception error){MessageBox.Show(error.Message,"安装未完成",MessageBoxButtons.OK,MessageBoxIcon.Error);folder.Enabled=browse.Enabled=shortcut.Enabled=install.Enabled=true;}}
}
class Setup {
 [STAThread] static int Main(string[] args){bool silent=false,shortcuts=false;string target=InstallEngine.DefaultPath;foreach(string arg in args){if(arg=="/silent")silent=true;if(arg=="/shortcuts")shortcuts=true;if(arg.StartsWith("/dir="))target=arg.Substring(5);}if(silent){try{InstallEngine.Install(target,shortcuts,(n,s)=>{});return 0;}catch(Exception error){try{File.WriteAllText(Path.Combine(Path.GetTempPath(),"GameDesignerWorkerSpace-install-error.txt"),error.ToString());}catch{}return 1;}}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new InstallerForm(target));return 0;}
}
